<script setup>import {ref,computed} from 'vue';import {doc,updateDoc} from 'firebase/firestore';import {db} from '../firebase';import {uploadSmall} from '../services/data';const props=defineProps(['user','profile']);const emit=defineEmits(['toast']);const bio=ref(props.profile.bio||''),twitter=ref(props.profile.socials?.twitter||''),youtube=ref(props.profile.socials?.youtube||''),github=ref(props.profile.socials?.github||''),file=ref(null),saving=ref(false);const xp=computed(()=>props.profile.xp||0),level=computed(()=>Math.floor(xp.value/200)+1),pct=computed(()=>((xp.value%200)/2)),title=computed(()=>level.value>=40?'YENİLMEZ':level.value>=20?'Kral':level.value>=10?'Azimli':level.value>=5?'Kıdemli':'Üye');async function save(){saving.value=true;try{let photoURL=props.profile.photoURL||'';if(file.value)photoURL=await uploadSmall(props.user.uid,file.value,'profile');await updateDoc(doc(db,'users',props.user.uid),{bio:bio.value,socials:{twitter:twitter.value,youtube:youtube.value,github:github.value},photoURL,updatedAt:new Date()});emit('toast','Profil kaydedildi.')}catch(e){emit('toast',e.message)}finally{saving.value=false}}</script><template><div class="card"><div class="space"><div><div class="tags"><span class="tag">{{profile.role}}</span><span class="tag">{{title}}</span></div><h1>{{profile.displayName}}</h1><p class="muted">@{{profile.uid.slice(0,8)}}</p></div><img v-if="profile.photoURL" :src="profile.photoURL" class="avatar-lg"><div v-else class="avatar-lg" style="display:grid;place-items:center;background:var(--surface2);font-size:32px">{{profile.displayName?.slice(0,1)}}</div></div><div class="space"><b>{{xp}} XP</b><span class="muted">Seviye {{level}} · {{200-(xp%200)}} XP kaldı</span></div><div class="xp"><i :style="{width:pct+'%'}"></i></div><br><label>Profil fotoğrafı</label><input class="field" type="file" accept="image/*" @change="file=$event.target.files[0]||null"><label>Görünen ad</label><input class="field" :value="profile.displayName" disabled><small v-if="profile.role==='DEVELOPER'" class="muted">DEVELOPER hesabının adı Mavi olarak sabitlenmiştir.</small><label>Açıklama</label><textarea class="field" rows="4" v-model="bio" maxlength="500"></textarea><div class="grid"><input class="field" v-model="twitter" placeholder="Sosyal linki"><input class="field" v-model="youtube" placeholder="YouTube linki"><input class="field" v-model="github" placeholder="GitHub linki"></div><button class="btn" :disabled="saving" @click="save">{{saving?'Kaydediliyor...':'Profili kaydet'}}</button></div></template>